// Access ALL input items
const items = $input.all();
const results = [];

// Process each lead
for (const item of items) {
  // Safety check: skip if no valid data
  if (!item.json || (!item.json.person && !item.json.organization)) {
    console.log('⚠️ Skipping invalid item:', item);
    continue;
  }

  // Apollo wraps data in a "person" object
  const lead = item.json.person || item.json;
  const org = lead.organization || {};

  // Get tech stack as comma-separated string
  const techStack = org.technology_names?.join(', ') || 'Not detected';

  // Get top keywords
  const topKeywords = org.keywords?.slice(0, 10).join(', ') || 'Not available';

  // Format the complete enriched data
  const enrichedData = {
    // Field 1: Company name
    company_name: org.name || '',

    // Field 2: Company website
    company_website: org.website_url || '',

    // Field 3: Industry / niche
    industry: org.industry || '',

    // Field 4: Number of employees
    num_employees: org.estimated_num_employees || '',

    // Field 5: Country
    country: lead.country || org.country || '',

    // Field 6: Contact person full name
    contact_name: `${lead.first_name || ''} ${lead.last_name || ''}`.trim(),

    // Field 7: Job title
    job_title: lead.title || '',

    // Field 8: Business email (verified)
    business_email: lead.email || '',

    // Field 9: LinkedIn profile URL (personal)
    linkedin_profile: lead.linkedin_url || '',

    // Field 10: LinkedIn company page URL
    linkedin_company: org.linkedin_url || '',

    // Field 11: Tools/software used
    tools_software: techStack,

    // Field 12: Short note - we'll generate with AI next
    short_note: '[TO BE GENERATED BY AI]',

    // ENRICHMENT FIELDS (Stage 5)
    company_description: org.short_description || '',
    founded_year: org.founded_year || '',
    company_phone: org.phone || '',
    top_keywords: topKeywords,
    seniority: lead.seniority || '',

    // Internal tracking
    date_added: new Date().toISOString(),
    apollo_id: lead.id || '',
    email_status: lead.email_status || 'unknown'
  };

  results.push({ json: enrichedData });
}

return results;

