const items = $input.all();
const results = [];

for (const item of items) {
  const leadData = item.json;

  // The AI node returns output in different structures depending on version
  let aiOutput;

  // Try multiple possible locations for AI response
  if (leadData.output && Array.isArray(leadData.output)) {
    // Structure 1: output[0].content[0].text (chat completion format)
    if (leadData.output[0]?.content?.[0]?.text) {
      aiOutput = leadData.output[0].content[0].text;
    }
    // Structure 2: output[0].text (simple format)
    else if (leadData.output[0]?.text) {
      aiOutput = leadData.output[0].text;
    }
    // Structure 3: output[0] is string
    else if (typeof leadData.output[0] === 'string') {
      aiOutput = leadData.output[0];
    }
  }
  // Structure 4: Direct text field
  else if (leadData.text) {
    aiOutput = leadData.text;
  }
  // Structure 5: Direct message field
  else if (leadData.message) {
    aiOutput = leadData.message;
  }

  // If still no output found, log and use fallback
  if (!aiOutput) {
    console.log(`⚠️ Could not find AI output for ${leadData.company_name}`);
    console.log('Available keys:', Object.keys(leadData));
    console.log('Full data sample:', JSON.stringify(leadData).substring(0, 500));

    // Build final lead with fallback AI data
    const finalLead = {
      company_name: leadData.company_name,
      company_website: leadData.company_website,
      industry: leadData.industry,
      num_employees: leadData.num_employees,
      country: leadData.country,
      contact_name: leadData.contact_name,
      job_title: leadData.job_title,
      business_email: leadData.business_email,
      linkedin_profile: leadData.linkedin_profile,
      linkedin_company: leadData.linkedin_company,
      short_note: "This SMB is in the ideal growth stage (5-50 employees) and would benefit from automation solutions to streamline operations and enhance efficiency.",
      qualification_score: "Medium",
      score_reasoning: "Manual review required - AI response format not detected"
    };

    results.push({ json: finalLead });
    continue;
  }

  // Enhanced JSON cleaning
  let cleanJson = aiOutput
    .replace(/```json\n?/gi, '')
    .replace(/```\n?/g, '')
    .replace(/^[^{]*/g, '')  // Remove text before first {
    .replace(/[^}]*$/g, '')  // Remove text after last }
    .trim();

  // Parse and validate AI response
  let aiData;
  try {
    aiData = JSON.parse(cleanJson);

    // Validate all required fields exist and are non-empty
    if (!aiData.short_note || aiData.short_note.trim() === '') {
      throw new Error('Missing or empty short_note');
    }
    if (!aiData.qualification_score || !['High', 'Medium', 'Low'].includes(aiData.qualification_score)) {
      throw new Error(`Invalid qualification_score: ${aiData.qualification_score}`);
    }
    if (!aiData.score_reasoning || aiData.score_reasoning.trim() === '') {
      throw new Error('Missing or empty score_reasoning');
    }

  } catch (e) {
    console.log(`⚠️ JSON parsing failed for ${leadData.company_name}: ${e.message}`);
    console.log(`Raw AI output (first 300 chars): ${aiOutput.substring(0, 300)}`);

    // Attempt to extract data with regex as fallback
    const shortNoteMatch = aiOutput.match(/"short_note"\s*:\s*"([^"]+)"/);
    const scoreMatch = aiOutput.match(/"qualification_score"\s*:\s*"(High|Medium|Low)"/i);
    const reasoningMatch = aiOutput.match(/"score_reasoning"\s*:\s*"([^"]+)"/);

    if (shortNoteMatch && scoreMatch && reasoningMatch) {
      console.log(`✅ Recovered data using regex for ${leadData.company_name}`);
      aiData = {
        short_note: shortNoteMatch[1],
        qualification_score: scoreMatch[1],
        score_reasoning: reasoningMatch[1]
      };
    } else {
      // Ultimate fallback
      aiData = {
        short_note: "This European SMB with 5-50 employees is in a prime growth stage where automation and AI solutions can streamline operations, reduce manual tasks, and drive efficiency gains.",
        qualification_score: "Medium",
        score_reasoning: "Automatic qualification based on company size and industry fit (AI parsing failed)"
      };
    }
  }

  // Build final lead object
  const finalLead = {
    company_name: leadData.company_name,
    company_website: leadData.company_website,
    industry: leadData.industry,
    num_employees: leadData.num_employees,
    country: leadData.country,
    contact_name: leadData.contact_name,
    job_title: leadData.job_title,
    business_email: leadData.business_email,
    linkedin_profile: leadData.linkedin_profile,
    linkedin_company: leadData.linkedin_company,
    short_note: aiData.short_note,
    qualification_score: aiData.qualification_score,
    score_reasoning: aiData.score_reasoning
  };

  results.push({ json: finalLead });
}

console.log(`✅ Successfully processed ${results.length} leads`);
return results;

